#!name=vgTime
#!desc=某些APP要清除缓存或者重新安装拦截广告才会生效！
#!author=奶思
#!homepage=https://github.com/fmz200/wool_scripts
#!icon=https://raw.githubusercontent.com/fmz200/wool_scripts/main/icons/gif/naisi-01.gif
#!raw-url=https://github.com/fmz200/wool_scripts/raw/main/Loon/plugin/split/partV/vgTime.lpx
#!tg-channel=https://t.me/inaisi
#!date=2026-11-11 21:17:23
#############################################


[Argument]
vgtime_enable = switch,true,false,tag=vgTime-脚本开关

[Script]
# App去开屏广告(需全新应用). 若要去新闻列表广告需要搭配广告联盟模块
response if ${url} ~= /^https?:\/\/app02\.vgtime\.com:8080\/vgtime-app\/api\/v2\/init\/ad\.json/i then script("https://raw.githubusercontent.com/app2smile/rules/master/js/vgtime.js") with enable=${vgtime_enable}, tag="vgTime", timeout=60, requires_body=true

[MITM]
hostname = app02.vgtime.com
